update content_bodies set title = '【Vol.3】＃キバレかごしまプロジェクト～私たちの手で鹿児島を元気に～', description = '「＃キバレかごしまプロジェクト～私たちの手で鹿児島を元気に～」の待望の第三弾！！

鹿児島県かごしまＰＲ課では、新型コロナウィルスとの厳しい戦いの中頑張っているかごしまの皆さんに向けて、少しでも前向きになって貰えるようなメッセージ動画を、かごしまを愛する皆さんと共に制作し，配信しています。
今回の＃キバレメッセージは，市民吹奏楽団ウィンド・オーケストラ”フォレ”のマーチ｢Fly to the Star｣の爽やかなメロディに乗せて，ご紹介します！
※メッセージは、応募のあった順に公開しています。

≪出演≫
かごしまを愛する皆さん
1．明桜館高校吹奏楽部 
2．株式会社トヨタレンタリース鹿児島 
3．九州電力株式会社 鹿児島支社 
4．Ｓ☆ＵＴＨＥＲＮ　ＣＲＯＳＳ　及川真依
5．＠takashi__masunaga
6．スカイマーク株式会社 鹿児島空港支店
7．Ｓ☆ＵＴＨＥＲＮ　ＣＲＯＳＳ　夢野ひかり 
8．種子島アクションクラブ・離島閃隊タネガシマン
9． パッションフルーツ生産者と大崎町職員
10．Ｓ☆ＵＴＨＥＲＮ　ＣＲＯＳＳ　佐倉しおり
11．子供たち 
12．Ｓ☆ＵＴＨＥＲＮ　ＣＲＯＳＳ　三上メイサ 
13．株式会社　南日本フーズ
14．姶良市 大阪風お好焼き　孝子庵
