update content_bodies set title = '[Vol.3] #Kibare Kagoshima Project - Let''s Revitalize Kagoshima with Our Own Hands -', description = 'The long-awaited third installment of the ''#Kibare Kagoshima Project - Let''s Revitalize Kagoshima with Our Own Hands -'' is here!!

The Kagoshima PR Division is producing and distributing message videos with the support of those who love Kagoshima, aimed at encouraging everyone in Kagoshima who is fighting hard against the severe battle with the COVID-19 virus to feel a little more positive.
This time, the #Kibare message will be introduced with the refreshing melody of the march ''Fly to the Star'' by the Kagoshima Citizens'' Wind Orchestra ''Fore''!
*Messages are released in the order they were submitted.

≪Participants≫
Everyone who loves Kagoshima
1. Kagoshima Prefectural Meisukan High School Wind Orchestra
