update content_bodies set title = '[Vol.2] #Kibare Kagoshima Project - Let''s Energize Kagoshima with Our Hands -', description = 'The Kagoshima PR Division of Kagoshima Prefecture is producing and distributing message videos with the people who love Kagoshima, aimed at encouraging everyone in Kagoshima who is working hard in the tough battle against the novel coronavirus to feel a little more positive.
This time, we present the long-awaited second installment of the ''#Kibare Kagoshima Project - Let''s Energize Kagoshima with My Hands!'' 
*Messages are released in the order they are received.

