update content_bodies set title = '【伊東市PR】僕の街は観光地 - My hometown is a city that seduces a lot of people -', description = '『第4回日本国際観光映像祭 日本部門 Vlog 優秀作品』

コロナ禍による「観光地」の衰退が囁かれる今だからこそ、
その地の魅力を再確認する必要がある。

僕の育った「伊東」にはたくさんの「光源」があり、それを照らしに全国からたくさんの方が足を運んでくれる姿を見てきた。

観光地というのは、訪れてくれる人の存在があって初めて最大の魅力を発揮する。

そんな素敵な魅力を届けるため、拡散お願いします。

＃伊東市　＃伊東　＃静岡県

