update content_bodies set title = '家族旅行村「安心院」', description = '家族旅行村「安心院」は、大自然のなかでご家族・ご友人と気ままにのんびりと別荘感覚でご利用いただける本格的ログハウスをはじめ、お子様からお年寄りまで世代を超えて気軽に楽しめるパークゴルフ場などのスポーツ施設、疲れた体を癒してくれる温泉など、魅力あふれる複合レジャー施設です。
また近年、注目を集めているオートキャンプ場は、最大１６張りのテントを設置することができ、バーベキューや昆虫採集、天体観測などをお楽しみいただけます。
家族旅行村「安心院」で、大自然を感じながら、ゆったりとしたひと時をお楽しみください。

