update content_bodies set title = 'Ajimu Family Travel Village', description = 'Ajimu Family Travel Village offers a variety of attractions, including authentic log cabins where families and friends can relax in a villa-like atmosphere amidst nature, sports facilities such as a park golf course that can be enjoyed by all generations from children to the elderly, and hot springs that soothe tired bodies. 
In recent years, the auto camping site has gained attention, allowing for the setup of up to 16 tents, where you can enjoy barbecues, insect collecting, and stargazing. 
Experience the great outdoors and enjoy a leisurely time at Ajimu Family Travel Village.' where id = 'qDRnUmFZyLidm9SC_XI5H';
