update content_bodies set title = 'Fisherman''s Wharf Shirahama', description = 'This facility is operated by local fishermen. The first floor is a fresh fish market, and the second floor is a restaurant, with a seasonal beer garden on the rooftop.
Please enjoy Japanese and Italian cuisine that makes abundant use of fresh ingredients directly landed from the pier attached to the facility.' where id = 'gq-O-oL0ipv78pUglPvSO';
update content_bodies set title = '三段壁 シネマティック', description = '千畳敷の南海岸にそそり立つ高さ50m～60mの断崖。
その昔、漁師たちが通りゆく船や魚の群れを見張った場所「見壇」に由来するといわれるこの大岩壁は、南北2kmにわたって展開され、岩肌に打ち寄せる黒潮が激しくぶつかり合うダイナミックな光景には、自然の迫力を感じずにいられません！
2016年4月、恋人の聖地｢南紀白浜/三段壁｣として選定されました' where id = 'i2GNvbSyFfTU_T4V7AONI';
update content_bodies set title = 'Sandanbaki Cinematic', description = 'A 50m to 60m high cliff towering over the southern coast of Chijōzaki.
This massive rock wall, said to be named after the place ''Midan'' where fishermen once watched over passing ships and schools of fish, extends for 2 kilometers from north to south. The dynamic scene of the Kuroshio current crashing against the rocky surface is a sight that cannot help but evoke the power of nature!
In April 2016, it was selected as a ''Sacred Place for Lovers'' in Nanki Shirahama/Sandanbaki.' where id = 'sZSzMCGCz7oOHTS7_2SKm';
