update content_bodies set title = 'My Year 2021 | Cinematic JAPAN | Shunpei Kawai', description = 'My Year 2021 
これまで関わってくれた方に感謝します
この1年間、僕は旅に出た。
自転車で日本一周やヒッチハイクで九州一周など色々なことに挑戦してきました。
その旅の中で僕はカメラに出会った。
日本中を旅をしたこの1年を1本の動画にしました。
映像を初めて丸1年。これからも自分の人生を映像を通して表現していきます。

Last year I met a camera and started video.

The video made my life better.
In 2021, I cycled around Japan.
Travelling throughout Japan, I rediscovered the charm of our country. 
And I have captured the beauty on film and have shared with many people. 

Please take a look from the link on my profile！

#Myyear2021 #CinematicVideo #CinematicJapan #Japan #sony #dji #mavicair2 #sonyα

