update content_bodies set title = 'My Year 2021 | Cinematic JAPAN | Shunpei Kawai', description = 'My Year 2021
I would like to thank everyone who has been involved with me so far.
This past year, I went on a journey.
I challenged myself with various things, such as cycling around Japan and hitchhiking around Kyushu.
During that journey, I encountered a camera.
I have compiled this year of traveling throughout Japan into a single video.
It has been a full year since I started making videos. I will continue to express my life through film.

Last year I met a camera and started video.

The video made my life better.
In 2021, I cycled around Japan.
Travelling throughout Japan, I rediscovered the charm of our country.
And I have captured the beauty on film and have shared with many people.

Please take a look from the link on my profile！

