update content_bodies set title = '【神奈川Vlog】旅人の食べ歩きをcinematicに表現してみた', description = 'こんにちは、河合舜平です！
バックパッカーの旅の日常を発信しています。
是非チャンネル登録していただければ嬉しいです！

