update content_bodies set title = 'Cinematic Coffee Video | Chai Tea Heron | Sony a6600', description = 'Hello, I''m Shunpei Kawai!

I share the daily life of a backpacker in a cinematic way.

This time, I made a cinematic video when I visited a cafe where I became friends with someone at a guesthouse.

Chai Tea Heron
1-4-22 Omiya, Chuo Ward, Fukuoka City, Fukuoka Prefecture
Open 12:00 Close 20:00 Last Order 19:30
Closed on Thursdays - Chai specialty store
Using organic black tea from Ukiha and brown sugar from Hateruma Island, we grind about 12 types of whole spices and brew each cup of chai upon order.
From standard to unique varieties.

_____
You can find Chai Tea Heron on social media here:
