update content_bodies set title = '奄美群島 Amami Islands, Japan in 8K', description = '奄美群島は、鹿児島の南方380～580キロメートルの海上に点在する８つの有人島（奄美大島、加計呂麻島、請島、与路島、喜界島、徳之島、沖永良部島、与論島）から成り立ち、亜熱帯の自然には固有種も含め、珍しい生き物も多数生息しています。「ハブ」が生息する島、サンゴが隆起してできた島、世界に誇る鍾乳洞が地下に広がる島など、それぞれの島に魅力的なポイントがたくさんあります。

