update content_bodies set title = 'Amami Islands, Japan in 8K', description = 'The Amami Islands consist of eight inhabited islands (Amami Oshima, Kakeroma Island, Kikaijima, Yorojima, Kikai Island, Tokunoshima, Okinoerabu Island, and Yoron Island) scattered over the sea 380 to 580 kilometers south of Kagoshima. The subtropical nature includes many rare creatures, including endemic species. Each island has many attractive points, such as islands where ''habu'' snakes live, islands formed by raised coral, and islands with world-renowned limestone caves underground.

