update content_bodies set title = 'Cherry Blossoms in Nakatsugawa【Honmachi Park】short version', description = 'This is a series introducing the famous cherry blossom spots in Nakatsugawa City, Gifu Prefecture.

Here are the cherry blossoms of "Honmachi Park," located in the city center of Nakatsugawa.
There are cherry blossom tree-lined streets on both sides of the park, and every year, many citizens visit for hanami.
The cherry blossom trees lining the promenade, known as the Mini Nakasendo, create a tunnel of blossoms.
The park also features an outdoor stage and various play equipment, as well as a display of the steam locomotive "D51."

Filmed with a drone on March 26, 2021.
Enjoy the cherry blossoms of Nakatsugawa in 4K video.

Here is the Nakatsugawa Tourism Association''s website.
