update content_bodies set title = 'クリス・ペプラーさん 福知山城 新城主 就任記者会見【明智光秀が築いた城】', description = '=====================================================
　　　　　　　　　　＼　重　大　発　表　／　　　　　　　　2019年6月6日更新
　　　明智光秀が築いた「福知山城」24時間自由に使えます！
　　　　　「日本初」の一日城主を公募！ 7月5日まで
　 https://www.city.fukuchiyama.lg.jp/site/promotion/11936.html
=====================================================
（動画の中で、クリス・ペプラーさんが発表を止められていた内容がこちらです！）

---------------------------------------------------------------------------------------------------------------------------------
　　　　　　　　　　　　　　　　　　　　　　　　　　　　　2019年3月27日

＜京都府福知山市プロモーション動画『福知山城 新城主就任記者会見』を公開！
明智光秀の子孫とされるクリス・ペプラーさん主演、重大発表に乞うご期待？＞

福知山城を築いた戦国武将・明智光秀の子孫とされるクリス・ペプラーさんが「福知山城 新城主」に就任！
お披露目記者会見で突如、重大発表をしようとするが・・・！？

クリス・ペプラーさんは髷を結い、明智家の家紋である「桔梗紋」があしらわれた天正裃（てんしょうかみしも）を身に着けた「殿様姿」で記者会見に登場、
新城主就任への抱負を熱く語ります。

福知山市は、明智光秀の知られざる魅力と福知山市とのつながりを全国に発信する「知られざる明智光秀プロジェクト」に取り組んでいます！

福知山市と明智光秀のゆかりについてはこちらをチェック！
https://www.city.fukuchiyama.lg.jp/site/mitsuhide/

（福知山PR事業　自治体PR動画）' where id = 'UUKN-m9gnoIZDoKMwWdqk';
update content_bodies set title = 'Chris Peppler''s Press Conference for the New Lord of Fukuchiyama Castle【A Castle Built by Akechi Mitsuhide】', description = '===================================================== 
　　　　　　　　　　＼　Major Announcement　／　　　　　　　　Updated June 6, 2019 
　　　Fukuchiyama Castle, built by Akechi Mitsuhide, is now available for use 24 hours a day! 
　　　　　Applications for Japan''s first one-day lord are now open! Until July 5 
　 https://www.city.fukuchiyama.lg.jp/site/promotion/11936.html 
===================================================== 
(This is the content that Chris Peppler was about to announce in the video!) 

--------------------------------------------------------------------------------------------------------------------------------- 
　　　　　　　　　　　　　　　　　　　　　　　　　　　　　March 27, 2019 

<Kyoto Prefecture Fukuchiyama City Promotion Video ''Press Conference for the New Lord of Fukuchiyama Castle'' Released! 
Starring Chris Peppler, said to be a descendant of Akechi Mitsuhide, stay tuned for a major announcement?> 

Chris Peppler, said to be a descendant of the Warring States general Akechi Mitsuhide who built Fukuchiyama Castle, has been appointed as the ''New Lord of Fukuchiyama Castle''! 
During the unveiling press conference, he suddenly attempts to make a major announcement...!? 

Chris Peppler appeared at the press conference dressed as a lord, wearing a topknot and the ''Kikyo'' family crest of the Akechi clan, in a traditional Tensho kamishimo, 
passionately expressing his aspirations for his new role as lord. 

Fukuchiyama City is working on the ''Unknown Akechi Mitsuhide Project'' to promote the unknown charms of Akechi Mitsuhide and its connection to Fukuchiyama City nationwide! 

Check out the connection between Fukuchiyama City and Akechi Mitsuhide here! 
https://www.city.fukuchiyama.lg.jp/site/mitsuhide/ 

(Fukuchiyama PR Project Local Government PR Video)' where id = 'q7GV6694r5mQZvxo9soVh';
