update content_bodies set title = '美の感覚。「日本の優雅さ、栃木」', description = '公式: https://www.tochigi.global

野に咲く色彩、紫陽花、ゆり、青竹、紅葉は自然の本質の根源です。
忘れられない栃木は、四季の自然の美しさで織り成された衣装を身にまとっています。

---

紫陽花、ゆり、青竹、紅葉など野に咲く彩りは、私たち人間の美意識の根源。四季織々の自然の美しさが織り込まれた装束を身に纏い、舞い踊る栃木。「美の感覚、栃木」。

