update content_bodies set title = 'Enjoy 4 to 5 varieties of strawberry picking at ''#Koyagakiuchi Farm''. The strawberries grown using the temperature differences in #HidaTakayama are characterized by their concentrated flavor and strong sweetness. No reservation is required, and you can eat as much as you want from the start time until 3 PM.', description = '' where id = '5hPEWHdF2aQjhemV3GOCq';
update content_bodies set title = 'ざらめで作る綿菓子を溶かしながら食べる絶品すき焼きが人気「#岩ト屋」。A5等級 #飛騨牛 を 使用したすき焼きやとろけるような食感と大きな綿菓子が特徴。飛騨エリアの特産品が入っています。#飛騨高山', description = '' where id = 'VbdDgV31K5pJ5h56drAnb';
update content_bodies set title = 'The popular ''Iwatoya'' offers exquisite sukiyaki made with melted sugar and cotton candy. Featuring A5 grade Hida beef, this sukiyaki is characterized by its melt-in-your-mouth texture and large cotton candy. It includes local specialties from the Hida area. #HidaTakayama', description = '' where id = '8SkvPv5girNZztTy8lNVU';
update content_bodies set title = '#飛騨高山 へようこそ', description = '日本一面積が広い市である高山市は、町のすみずみまでたくさんの見どころに溢れています。飛騨山脈(北アルプス)に抱かれ、豊かな自然と四季折々の美しい景色に癒される、多彩な魅力を持つエリアです。ここでしか味わえない感動体験をあなたに。
「あわまいか　飛騨高山」

