update content_bodies set title = 'せせらぎが聴こえる町　#飛騨清見', description = '森に囲まれたおしゃれなカフェやレストランが点在する清見町は、洗練された雰囲気とのどかな自然が共存。町の中央を南北に縦断する全長64㎞の「飛騨美濃せせらぎ街道」は、格好のドライブルート。清流沿いで、初夏には新緑が輝きます。また、秋には紅葉の名所として知られ、標高差によって色づく場所が移り変わることで長期に渡り目を楽しませてくれます。

