update content_bodies set title = 'The Town Where You Can Hear the Murmuring Stream #HidaKiyomi', description = 'Kiyomi Town, dotted with stylish cafes and restaurants surrounded by forests, is a place where a sophisticated atmosphere coexists with tranquil nature.
The ''Hida-Mino Seseragi Road,'' which runs north-south through the center of the town for a total length of 64 km, is an ideal driving route.
Along the clear stream, fresh greenery shines in early summer.
In autumn, it is known as a famous spot for autumn leaves, and the changing colors due to the elevation differences provide a long-lasting visual delight.' where id = 'bZN4QlYOG51AcUJR_y_vB';
update content_bodies set title = 'レトロなブリキの看板など昭和の雰囲気が漂う「#福地温泉朝市」。味噌などの名物やお菓子などの商品が並びます。店内は昭和のポスターなど昔のアイドルや俳優の写真がいっぱい！#飛騨高山', description = '' where id = 'e5yf0AhjM7VFseoCntBtY';
update content_bodies set title = 'Retro tin signs and the atmosphere of the Showa era at ''#Fukuchi Onsen Morning Market''. Specialties like miso and various snacks are lined up. The store is filled with old posters and photos of past idols and actors from the Showa era! #Hida Takayama', description = '' where id = 'yYIMjaqRvUXXep7umVkaI';
update content_bodies set title = '日本唯一の２階建てゴンドラに乗って、気軽に北アルプス360°大パノラマの絶景を見られる「#新穂高ロープウェイ」。冬の季節しか見ることができない幻想的な風景や限定イベントが目白押しです。#飛騨高山', description = '' where id = 'nXiyPgOtkJE7RmH_31DA_';
update content_bodies set title = 'Ride Japan''s only two-story gondola and easily enjoy the breathtaking 360° panorama of the Northern Alps at ''#Shinhotaka Ropeway''. A variety of fantastic landscapes and limited events can only be seen in the winter season. #HidaTakayama', description = '' where id = '9gRYAz-1gMefgUTbpFQN_';
update content_bodies set title = '新平湯の名所であるタルマの滝・親水公園で開催される「#新平湯温泉 #タルマかねこおりライトアップ」。息を吞む美しさで圧倒される、今まで体験したことがないような神秘的な風景が楽しめます。#飛騨高山', description = '' where id = 'eqhEHPtOig_yvWdNgS1fx';
update content_bodies set title = 'The ''#Shin-Hirayu Onsen #Tarma Kanekoori Light Up'' event held at the Tarma Falls and Shinsui Park, a famous spot in Shin-Hirayu. Experience breathtaking beauty and a mystical landscape like never before. #Hida Takayama', description = '' where id = 'PocTAisUiidHXJlOQIB6U';
update content_bodies set title = '歴史と自然が紡ぐ #岐阜県 #飛騨高山 「荘川町」', description = '荘川町は山々に囲まれ、荘川町の北西に位置し富山県、石川県、福井県、岐阜県の４県にまたがる「白山」の雄大な姿を眺望できる自然あふれる町です。桜、新緑、紅葉、雪景色と季節ごとに美しい四季折々の絶景を楽しむことができます。

