update content_bodies set title = 'History and Nature Weaving Together #Gifu Prefecture #Hida Takayama ''Shokawa Town''', description = 'Shokawa Town is surrounded by mountains and offers a view of the majestic ''Hakusan'', which spans four prefectures: Toyama, Ishikawa, Fukui, and Gifu, located to the northwest of Shokawa Town. You can enjoy the beautiful seasonal scenery throughout the year, including cherry blossoms, fresh greenery, autumn leaves, and snowy landscapes.

