update content_bodies set title = '#飛騨高山  #アルコピア #ひまわり　園', description = '～20万本のひまわりがゲレンデを彩る～
一面に広がる鮮やかな黄色が美しい「アルコピアひまわり園」。約20万本のひまわりがこちらに向かって一斉に咲き誇る姿は圧巻です。期間中にはジャンボしゃぼん玉、トランポリン、キッチンガーなど楽しめる催しが目白押し♡夏らしい1枚が撮影できる映えスポットです。ひまわりの見ごろは8月11日(金)ごろからとのことです。

【開催情報】
アルコピアひまわり園
住所：岐阜県高山市久々野町無数河4141
（ナビ検索　電話番号　0577-52-2219）
お問合せ：ひだ桃源郷くぐの観光協会　0577-52-2270
営業：9:00～16:00
期間：2023年8月5日(土)～20日(日)
※おひとり300円程度の美化整備協力金をお願いします。
駐車場：あり
中部縦貫自動車道路　高山ＩＣから車で約20分

~200,000 sunflowers decorate the ski slopes~
``Alcopia Sunflower Garden'''' is a beautiful, bright yellow garden. The sight of about 200,000 sunflowers blooming all at once is a sight to behold. During the period, there will be lots of fun events such as jumbo soap bubbles, trampolines, and kitchen gardens ♡ It''s a great spot where you can take a summer-like photo. The best time to see sunflowers is from around August 11th (Friday).

[Event information]
Arcopia Sunflower Garden
Address: 4141 Myriagawa, Kuguno-cho, Takayama City, Gifu Prefecture
(Navi search phone number 0577-52-2219)
Contact: Hida Togenkyo Kuguno Tourism Association 0577-52-2270
Business hours: 9:00-16:00
Period: August 5th (Sat) - 20th (Sun), 2023
*Please make a beautification maintenance donation of approximately 300 yen per person.
Parking: Yes
About 20 minutes by car from Chubu Jukan Expressway Takayama IC

