update content_bodies set title = '越前 手仕事を巡る旅  |  越前叡智 ーえちぜんえいちー  Craft Tourism Echizen MOVIE_01', description = '【手仕事を巡る旅 越前叡智】https://echizen-tourism.jp

ものづくりの聖地、越前
いにしえの時代から続く叡智の集積地へ

1500年も脈々と先人たちの技と心を受け継ぐまち。
いにしえの王が治めた「越の国」の入口、越前。
かつて日本海の向こうから最先端の技術と文化が真っ先に流入し、
日本の奥深いものづくりの起源となった、叡智の集積地。
土地の自然と共生する伝統的な産業やここでくらす人々の中に、
人類が次の1000年へ携えていきたい普遍の知恵が息づいています。
いまこの地で、国境や時空を越えて交流することで生まれる未来があります。
光を見つける新しい探究の旅。
ようこそ、越前へ。

