update content_bodies set title = '「里山ミニクル」で、観に来るたびに好きになる旅。', description = '「里山ミニクル」は、新型の電動アシスト付き自転車のレンタサイクルサービスです。
車両は、女性でも扱いやすいミニタイプのほか、シティータイプ・スポーツタイプの３種類を取りそろえており、電動アシスト付きのため坂道でも軽々登ることができます。
自転車の貸出場所には、おすすめのモデルコースや旅行に役立つガイドアプリをご用意しており、初めて利用する方でも気軽にご利用できます。
里山ミニクルは2時間コースや１泊２日でのご利用もいただけます。サイクリングを楽しむことも、旅の目的地へのお供としてもご自身の旅行スタイルに合わせてぜひご活用くださいませ。

"Satoyama Minicle: fall into the charm of your travels with every spin of the wheel."

「Satoyama Minicle」is a new kind of bicycle rental service offering electrically power assisted bikes. Riders are offered three kinds to choose from: a mini model accessible to any level of rider, an urban city model, and a sports model. These bikes allow riders to climb up even hilly roads with ease thanks to their electric power assist.
A guided app recommending routes and other useful information for one’s trip is also available at the bike rental counter, and is designed so that even first-time users can easily navigate it.

Satoyama Minicle bikes are available for 2-hour rental periods as well as overnight rentals. We hope you’ll take advantage of this service to suit your own travel style and enhance your destination plans! 


https://bit.ly/3Cb1fGo' where id = 'RDH56hi9MvbOFE0AIbfPg';
update content_bodies set title = 'With ''Satoyama Minicle'', a journey that makes you fall in love every time you visit.', description = '''Satoyama Minicle'' is a rental bicycle service offering new electric assist bikes. The vehicles come in three types: a mini model that is easy for women to handle, a city type, and a sports type, all equipped with electric assist to easily climb hills. At the bike rental location, we provide recommended model courses and a guide app useful for your trip, making it easy for first-time users to enjoy. Satoyama Minicle is available for 2-hour courses or overnight rentals. Whether you enjoy cycling or use it as a companion to your travel destination, please make the most of it according to your travel style.' where id = '1AYOnVqQIJa1HMilqnOF9';
update content_bodies set title = 'Japan''s tallest stone steps, 3333 steps　日本一の石段　3333段　釈迦院御坂遊歩道　英字幕付き　美里町観光PR動画', description = 'This is a Misato Town tourism PR video created in 2025.

These stone steps were built in Misaka, the main approach to the historic Shaka-in Temple (Izumi-cho, Yatsushiro City), which has a history of 1,200 years, and are the largest in Japan.They will be preserved for future generations as a century-old cultural heritage and will revitalize the town. It was built with the aim of creating a tourist attraction and a symbol of town revitalization.
Construction of the stone steps began in January 1980, and in November 1986, it surpassed the 2,446 steps of Mt. Haguro in Yamagata Prefecture to become the number one in Japan in both name and reality, and was completed at the end of March 1986.
In addition to famous stones from all over the country, these stone steps use granite from countries around the world such as China, South Korea, India, the former Soviet Union, Brazil, the United States, and South Africa.They are used to build international goodwill and friendship, and to promote historical exploration and health. It is used as a tourist and recreational facility.
Additionally, Attack the Nihon Ichi is held every November using the stone steps.
Some early climbers may take less than an hour to complete the climb, but for the general public, please expect it to take about 3 hours, including 2 hours for the ascent and 1 hour for the descent.


◇HP　http://misato.town/spot.html?id=68' where id = '4ZT_IxjCxvU8nLSGM5XuC';
update content_bodies set title = 'Japan''s tallest stone steps, 3333 steps', description = 'This is a Misato Town tourism PR video created in 2025.

These stone steps were built in Misaka, the main approach to the historic Shaka-in Temple (Izumi-cho, Yatsushiro City), which has a history of 1,200 years, and are the largest in Japan.
They will be preserved for future generations as a century-old cultural heritage and will revitalize the town.
It was built with the aim of creating a tourist attraction and a symbol of town revitalization.
Construction of the stone steps began in January 1980, and in November 1986, it surpassed the 2,446 steps of Mt. Haguro in Yamagata Prefecture to become the number one in Japan in both name and reality, and was completed at the end of March 1986.
In addition to famous stones from all over the country, these stone steps use granite from countries around the world such as China, South Korea, India, the former Soviet Union, Brazil, the United States, and South Africa.
They are used to build international goodwill and friendship, and to promote historical exploration and health.
It is used as a tourist and recreational facility.
Additionally, Attack the Nihon Ichi is held every November using the stone steps.
Some early climbers may take less than an hour to complete the climb, but for the general public, please expect it to take about 3 hours, including 2 hours for the ascent and 1 hour for the descent.

◇HP　http://misato.town/spot.html?id=68' where id = '2dtA-Gu_8XAbY1CsfrGYK';
update content_bodies set title = 'Hiking in Japan - Sacred Peak Mt. Hakkai 八海山 | Adventures in Yukiguni | Minamiuonuma', description = 'Climbing Mt. Hakkai (1778 m) of the Echigo Sanzan Mountains. Using the Hakkaisan Ropeway the hike took about 7 hours round-trip. 

Many tourists flock to Snow Country in the winter months to hit the slopes, but many of these snow resort grounds continue to attract visitors seeking outdoor adventures through mountain climbing in the summer as well. 

Mt. Hakkai is a famous mountain in Minamiuonuma that boasts a long history of dedicated climbers coming from all across the country. There are two impressive shrines dedicated to the mountain at each trail-head, and the mountain''s delicious spring water and impressive shape are part of the reason its name has become one of Japan''s most reputable sake brands: Hakkaisan. The mountain is very popular for tourists hiking on summer break and its lookout decks offer beautiful views of the varicolored Uonuma Basin in autumn once the leaves begin to change too. The mountains in this region are said to bless the locals with many gifts and in the green season these are manifested in the landscape''s breathtaking scenery.


Hakkaisan Ropeway Info: https://www.tohokukanko.jp/en/attractions/detail_1784.html
Visit Minamiuonuma: https://www.facebook.com/visitminamiuonuma/' where id = 'CqSos9anVNkh2Jfb58mIa';
