update content_bodies set title = '伊予市観光PR動画｜ますます、いよし。', description = '伊予市は、美しく豊かな自然や地元のとっておきのモノ・コトに出会う、癒しの旅にぴったりなところ。ゆったりと海を眺めたり、森の香りにつつまれたり、おいしいもの、パワースポット、クラフトなど今を楽しむときめきもいっぱい。今日はどこにいこうかな？　そんなときには、あなたの「好き」を探しに伊予市へでかけてみて。' where id = 'AW875t14u8FWLt_p40MlX';
update content_bodies set title = 'Iyo City Tourism PR Video | More and more, Iyo.', description = 'Iyo City is the perfect place for a healing journey where you can encounter beautiful and rich nature, as well as local treasures and experiences. Enjoy the moment with plenty of excitement, whether it''s gazing at the sea, being enveloped by the scent of the forest, or indulging in delicious food, power spots, and crafts. Where shall we go today? When you''re wondering about that, why not head to Iyo City to search for your ''likes''?' where id = 'xDiWBVjXbWRnEnXN1vKrp';
update content_bodies set title = 'roadside station Misato "Samata-no-Yu" 道の駅 美里「佐俣の湯」英字幕付き　美里町観光PR動画', description = 'This is a Misato Town tourism PR video created in 2025.

roadside station Misato "Samata-no-Yu" is a roadside station where the hot springs flowing directly from the source soothe the mind and body.
Roadside Station Misato "Samata no Yu" is located in the central part of Kumamoto Prefecture, along National Route 218 heading towards Nobeoka from Kyushu Expressway Matsubase IC. The facility features a natural hot spring facility with natural hot springs, a product store selling processed agricultural products produced by local farmers, a restaurant using local ingredients, and log house-style accommodations. In addition, in order to provide road and tourist information to those who come to the station, we have prepared public wireless LAN equipment that can be used outdoors and a dedicated website. We are trying to make it so that you can enjoy it.
