What is the furniture of the future? 
Okawa Furniture got an idea. 
It is “Robot Furniture.” 
It looks the same as other furniture, but it’s a mysterious furniture that walks by itself and stops on its own. It even spins around. 
This “Robot Furniture” will be a new partner in your life. 
It makes redecorating easy, it becomes a ride for children, and it makes your time at home more fun. 
Assembling innovative ideas with traditional technology. 
Okawa Furniture proposes rich lifestyles with its furniture.

For details on the robot furniture and behind-the-scenes stories about their creation, please view the special robot furniture webpage. 
https://www.okawa-kagu.net/robo
Contact us
okwsales_k@city.okawa.lg.jp
Website for Okawa City, Fukuoka Prefecture
https://www.city.okawa.lg.jp/

今後的家具到底會呈現何種樣貌？
大川家具已給出了答案。
顧名思義，它叫做「機器人家具」。
外觀看上去與以往的家具毫無二致，
但它自己會移動，會自己停下，還會轉向，
真的不可思議。
這樣的「機器人家具」將成為您生活中的新夥伴。
可輕鬆地改換佈局，亦可作為孩子們的騎乘玩具，
必將使您享受到更加歡樂的居家時光。
始於傳統技術，融入革新創意。
大川家具為您提案豐富多彩的家具生活。

