update content_bodies set title = 'Shokudo Ao - Eat Local - Taste the Unfolding Story of Kumano-', description = 'Introducing the notable restaurant ''Shokudo Ao'' in Kumano City, Mie Prefecture, featured in ''What Are the Wealthy Eating in Japan?''
The concept is ''Eat Local''.
In spring, we go foraging for local wild vegetables, in summer, we catch natural eel in the Dorokyo Gorge, and in autumn, we go out to catch sea crabs. Throughout the year, as long as the weather conditions are good, we kayak out into the sea of Kumano and serve fish that we have caught ourselves, maintaining a rare style of restaurant that is unimaginable in the city.
Come and hear about his passion.

For reservations at Shokudo Ao, please contact us via phone or DM here:
https://instagram.com/shokudo_ao?igshid=NTc4MTIwNjQ2YQ
tel 0597-70-4003
open 18:00-21:30 (Dinner)
*Please inquire about the availability of natural eel and other items.' where id = 'T8DkjiM4oq__TjP4tifmZ';
