update content_bodies set title = 'Well-being Living: Starting Citrus Cultivation - What Mandarins Teach Us', description = 'A couple searching for a well-being lifestyle moved from Tokyo to Mihama Town in Mie Prefecture, and more than three and a half years have passed.

Starting last year, we began cultivating mandarins in our garden, growing citrus fruits.

Growing a number of mandarin trees far exceeds the realm of a hobby, but we enjoy the effort it takes.

What does a well-being lifestyle mean to us?

What are the joys of life that we have never experienced before, beyond just growing mandarins?

For more information about Mihama Town in Mie Prefecture, please visit the website below:
https://mihama-mie-townpromotion.jp/

