#RuralLiving #RegionalRelocation #vlog' where id = '-1m91EkZsD6Ujm_2TJpsc';
update content_bodies set title = '【移住者の暮らし】里山暮らし｜移住ってどう？｜移住者の幸せな暮らし｜熊野｜地方移住｜サステナブル', description = '三重県御浜町尾呂志（おろし）
尾呂志は御浜町でも移住者が多いエリア。
美しい里山の風景と移住者を暖かく迎えてくれる地元の人たちのお陰で、
近年、都会から多くの人が移住してきている。
ある日、尾呂志を訪れた時に、何とも幸せそうな風景に出会った。
子供たちは里山を駆け回り、自然と遊ぶ。
大人たちも都会では出来なかったことを一つ一つ実現しながら、毎日を楽しそうに生きる。
尾呂志の人たちは同じ移住者のボクらから見ても羨ましく映る。

三重県御浜町について、詳しくは下記Webサイトをご覧下さい↓
https://mihama-mie-townpromotion.jp/

年中みかんのとれる町
三重県御浜町

紀伊半島、本州ほぼ最南端の太平洋沿いの町。
太平洋の海岸沿いには、約22kmに渡る七里御浜。
それは、古くから庶民に愛された祈りの路、世界遺産「熊野古道伊勢路」。
黒潮と温暖な気候のおかげで一年中、様々なみかんがとれる。
神秘的な紀伊山地と雄大な太平洋を有し、
青い山と青い海が出会う町。

「人生、出発たびだちの地」

熊野は「よみがえりの地」と言われてきました。古来より日本では、人々が生活を営む里に対し、山は神や祖先の霊が宿る神聖な場所である、という考え方があります。中でも熊野は神々が籠る深山の霊場であり、訪れた方は心魂が甦り、新たな気持ちになります。

月に2本の頻度で動画をアップしていく予定にしていますので、気に入って頂けたら、いいね、コメント、チャンネル登録の方、宜しくお願いします。インスタも始めました。

Instagram: https://www.instagram.com/rural_life_japan/

