update content_bodies set title = '[Life of Migrants] The Rumored Game Meat? | Tasting the Badger, Said to be the Most Delicious Game, Given by a Hunter Friend | Kumano | Regional Migration | Sustainable', description = 'Lyrically living in the countryside, once again, ''Traveling through Daily Life in the Japanese Countryside''.

Mihama Town, Mie Prefecture
One weekend, while cleaning the house,
I received a message from a hunter friend that a badger was caught this morning.
I hurriedly started preparing for the prosciutto of wild boar and smoked wild boar and deer meat,
and began the BBQ preparations.
I have read in a manga that badger is a delicacy among game meats.
The badger has a unique aroma, similar to lamb, and when eaten with cumin salt,
it is exquisite.

