#田舎暮らし #地方移住 #vlog' where id = '98PEWUsYB2swQZHCy77Zy';
update content_bodies set title = '[After Moving] The Day I Made Friends in the Countryside | About One Month After Moving from Tokyo to Mie with My Partner | Kumano | Rural Relocation | Sustainable', description = 'July 2020
We moved from Tokyo to Mihama Town, Mie Prefecture.
After a two-week period of self-restraint, we finally began to return to normal life.
During this time, the people we met in Mihama Town organized a BBQ party for us. Feeling left behind in summer due to the inability to return home or travel during COVID, it felt like we finally caught up with summer by being able to do something summery.

We started looking for a place to relocate in January of this year, and fortunately visited Mie Prefecture''s Mihama Town, Wakayama, and the eastern Kishu area just before the restrictions on outings in March due to COVID. However, after that, we were unable to visit the area, and since we couldn''t go research other places, we decided to move to Mihama Town, which felt like a fateful encounter. It was a decision made in about six months. Moving to a town with no connections or ties, and ultimately deciding to relocate to a town we only visited for a few hours in March took courage, but I think I was able to make that decision because I felt that if I continued searching, it would take years to relocate.

For more information about Mihama Town, please visit the website below:
https://mihama-mie-townpromotion.jp/

The Land of Resurrection, Kumano
The town of Kumano, Mihama Town, Mie Prefecture

Kumano has been referred to as the "Land of Resurrection." Since ancient times in Japan, there has been a belief that while the villages where people live are ordinary, mountains are sacred places where the spirits of gods and ancestors reside. Among them, Kumano is a sacred site where deities dwell, and those who visit feel their spirits revived and gain a new perspective.
This is why it is said to be "the land of life''s departure."
Additionally, the natural faith that has continued since before recorded history, the mountain religion represented by Kumano Shugendo, and the belief system that sees gods and Buddhas as one have combined to create a soil that nurtures Japan''s unique religious views.

Quoted from the Kumano Hongu Taisha website

