Rural Japan ♯7 A New Chapter Begins

Today, we show you our first day in the new place.
We love Tokyo, However, we couldn’t imagine living there for the rest of our life.
That’s why we decided to move out to Rural Japan.
Since this January, we had been searching for a place to live in rural area of Japan.
However, because of Covid-19, it was difficult to look around where we want to visit.
During this difficult time, we had an unexpected encounter by chance in Mie.
Although there were not enough time to see around, we fell in love with a town, Mihama.
Because of it,  we decided to move out there from Tokyo.
This is a new chapter of our life.




熊野は「よみがえりの地」と言われてきました。古来より日本では、人々が生活を営む里に対し、山は神や祖先の霊が宿る神聖な場所である、という考え方があります。中でも熊野は神々が籠る深山の霊場であり、訪れた方は心魂が甦り、新たな気持ちになります。

「人生、出発たびだちの地」

と言われる所以です。また、有史以前から続く自然信仰、熊野修験に代表される山岳宗教、そして神＝仏であるとする神仏習合の信仰形態が相まり、日本固有の宗教観を育む土壌ともなりました。

