#田舎暮らし #地方移住 #vlog' where id = '_8dzocecZouSAvxyPeHpj';
update content_bodies set title = '[First Day of Relocation] The Beginning of Our Relocation Life | A Couple Who Moved from Tokyo to Mie | Rural Living | Kumano | Regional Relocation | Sustainable', description = 'In July 2020,
we relocated from Tokyo to the town of Kumano, Mihama, Mie Prefecture.
This is a glimpse of our first day after the move.
We started searching for a place to relocate in January of this year, and just before the COVID-19 lockdown in March, we were fortunate enough to visit Mie Prefecture, including Mihama, as well as Wakayama and the eastern Kishu area. However, after that, we were unable to visit any other locations, and due to the research limitations, we decided to move to Mihama, a town we felt was destined for us. We made the decision to relocate in about six months.
It took courage to decide to move to a town with no connections or ties, especially since we had only visited for a few hours in March.
However, I thought that if we continued searching, it would take years to relocate, so I believe we were able to take the plunge.

For more information about Mihama Town, please visit the website below:
https://mihama-mie-townpromotion.jp/

We plan to upload videos once a week or once every two weeks, so if you like our content, please give us a thumbs up, leave a comment, and subscribe to our channel. We have also started an Instagram.

Instagram: https://www.instagram.com/rural_life_japan/

Rural Japan ♯7 A New Chapter Begins

Today, we show you our first day in the new place.
We love Tokyo, however, we couldn’t imagine living there for the rest of our life.
That’s why we decided to move out to Rural Japan.
Since this January, we had been searching for a place to live in the rural area of Japan.
However, because of Covid-19, it was difficult to look around where we wanted to visit.
During this difficult time, we had an unexpected encounter by chance in Mie.
Although there was not enough time to see around, we fell in love with a town, Mihama.
Because of it, we decided to move out there from Tokyo.
This is a new chapter of our life.

Kumano has been referred to as the "Land of Resurrection." Since ancient times in Japan, there has been a belief that mountains are sacred places where the spirits of gods and ancestors reside, while the villages where people live are not. Among them, Kumano is a spiritual site where gods dwell, and those who visit will have their hearts and souls revived, feeling renewed.

This is why it is said to be the "land of life''s departure."
Additionally, the natural faith that has continued since before recorded history, the mountain religion represented by Kumano Shugendo, and the belief system that sees gods and Buddhas as one have combined to create a soil that nurtures Japan''s unique religious perspective.

Quoted from the Kumano Hongu Taisha website.

About Kumano

"Kumano is a feeling - not a form - a manifestation of the Divine Intangibles, a celebration of life''s powerful vitality.
It is a peaceful place in nature to take a moment to reflect on, and reaffirm one''s future direction and meaning of life - a sacred space to open one''s mind, heart, soul; all of one''s senses; and let the artificial boundaries and borders of the modern world disappear - allowing us to contemplate life as one unified humanity on planet earth.
The importance of a pilgrimage to Kumano is not in its completion, but rather what you take home after internalizing your experience" (Kumano Kodo, 2019).

Kumano is the abode of the Gods.
The complicated landscape is considered a sacred site of healing and salvation for a diversity of faiths, and is a symbolic example of Japan''s syncretic religious traditions.

