There is much outstanding nature and life that will help you understand what Japanese people truly are.
We do not have symbolic icons or landmarks in the town.
However, it is a place to purify or relax, surrounded by a spiritual and sacred atmosphere.
There are also some Kumano Pilgrimage Routes, Ise Route, and some fantastic routes within the town.
In this difficult time, you might confront an opportunity to consider the meaning of life.
This place might be able to bring the answer you are searching for.
Please come to visit Mihama.

What kind of life are we searching for?

We are now searching for the meaning of life.
We come to see some people who show us their meaning of life in Mihama, Kumano.
Most people who moved to Kumano say it has sacred power,
and the power of Kumano leads us to live or visit here.
Once you come to visit Kumano, you will be able to understand what they are saying.
What kind of adventures are waiting for you?

We have received a lot of help here.

[Support Desk for Relocation and Exchange in Mihama Town]
If you are interested in relocating to Mihama Town, please do not hesitate to reach out. We received a lot of help here.
http://mihama-iju.com/

[Kumano Relocation Network]
If you are interested in relocating to Kumano City, please do not hesitate to reach out.
Unfortunately, we relocated to the neighboring Mihama Town, not Kumano City,
but thanks to the dedicated staff, it is not an exaggeration to say that our relocation to the eastern Kishu area was realized.
https://kumanoijunet.jimdofree.com/

#RuralLiving #RegionalRelocation #vlog' where id = 'WaSmZ-jU-ban-Z3yBfrAt';
update content_bodies set title = '【田舎の物語】ばあちゃんのみかん畑｜おばあちゃんのみかん畑を受け継いだ孫｜みかんのある暮らし｜熊野｜地方移住｜サステナブル', description = '御浜町に移住するまでは、こんな青いみかんがあることすら知らなかった。
9月上旬から収穫される、御浜町の強い夏の日差しの下で育った、
超極早生温州みかん。
その日差しがみかんの糖度を高くするそうです。
甘みと酸味の絶妙なバランスのみかんは非常に美味しかったです。
今年は天気が良く、みかんの日焼けが心配だったそうですが、
無事に出荷が始まりました。
※みかんの表面の白い斑点はホワイトコートというカルシウム由来の日焼け防止剤です。

超極早生温州みかんを皮切りに、御浜町では様々な種類のみかんが順次出荷されます。まさに、年中みかんのとれる町。

そのみかんの収穫の様子を、御浜町のちせ農園を通してお伝えできればと思います。
ちせ農園は現在、92歳になるちせさんからお孫さんに3年前に引き継がれたみかん農園になります。
おばあちゃんに敬意を込めて名前はそのままにしたそうです。
みかんを収穫する際のハサミの音色は心地よく、御浜町の秋の音だなと感じました。
また、家族総出でみかんを収穫する様子はまさにこの町の家族の肖像のように思えました。

三重県御浜町について、詳しくは下記Webサイトをご覧下さい↓
https://mihama-mie-townpromotion.jp/

月３〜４本の頻度で動画をアップしていく予定にしていますので、気に入って頂けたら、いいね、コメント、チャンネル登録の方、宜しくお願いします。インスタも始めました。

Instagram: https://www.instagram.com/rural_life_japan/

