In Mihama, many kinds of the mandarins are planted all around.
The first kind  in the season is the mandarins we see today.
This farm, named Chise farm, passed by from grandma to her grandchild about three years ago.
Chise farm named after her first name, Chise.
With respect, he didn''t change the name of it.
The sound of scissors while they are harvesting is very comfortable.
It''s a sound of Autumn in Mihama.
In addition, some family come to help for the harvesting. The scenery portraits a form of the family in this agricultural area.
If you see the mandarins in your town, please try to taste. It''s a taste of sun in Mihama.

