#田舎暮らし #田舎移住 #vlog' where id = 'NjjlkrVzT2sHXyZwox9ut';
update content_bodies set title = '[Rural Story] Grandma''s Mandarin Orchard | The Grandchild Who Inherited Grandma''s Mandarin Orchard | A Life with Mandarins | Kumano | Rural Relocation | Sustainable', description = 'I didn''t even know that such blue mandarins existed until I moved to Mihama Town.

Harvested from early September, these ultra-early maturing Satsuma mandarins are grown under the strong summer sun of Mihama Town.
That sunlight is said to increase the sugar content of the mandarins.
The mandarins, with their exquisite balance of sweetness and acidity, were incredibly delicious.
This year, the weather has been good, and there were concerns about sunburn on the mandarins, but the shipping has successfully begun.
*The white spots on the surface of the mandarins are a sunburn prevention agent called White Coat, derived from calcium.

Starting with the ultra-early maturing Satsuma mandarins, various types of mandarins will be shipped sequentially from Mihama Town. It truly is a town where mandarins can be harvested year-round.

I hope to convey the harvesting of these mandarins through Chise Farm in Mihama Town.
Chise Farm was passed down from 92-year-old Chise-san to her grandchild three years ago.
Out of respect for grandma, they decided to keep the name as it is.
The sound of scissors while harvesting the mandarins is pleasant, and I felt it was the sound of autumn in Mihama.
Additionally, the sight of the whole family coming together to harvest the mandarins seemed like a portrait of family life in this town.

For more information about Mihama Town, please visit the website below:
https://mihama-mie-townpromotion.jp/

We plan to upload videos 3 to 4 times a month, so if you enjoyed it, please like, comment, and subscribe to our channel. We have also started an Instagram.

