#RuralLiving #RuralRelocation #vlog' where id = 'gf9a_YgHHteWXz8rW4svE';
update content_bodies set title = '【移住のキッカケ】移住するキッカケになったお米を作る農家に会いにいく｜田舎暮らし｜熊野｜地方移住｜サステナブル', description = '昔から試したかったこと。
その土地のお米をそのお米が育った土地の水で炊く。
今まで色々と試したが、その方法が一番おいしくなる予感がする。

移住前、今年の3月に御浜町を訪問した時に、偶然出会った農家のお父さん。その時に東京から来たということで、お米を頂きました。
東京に帰ってそのお米を食べると信じられないほどおいしく、本当に感動しました。
しかし、一つの素朴な疑問が生まれました。
そのお米をそのお米が育った土地の水で炊いたらさらに美味しいのではないかと。
移住後、田舎は狭いもので、そのお父さんがこちらの数少ない知りあいの義理の父であることが判明し、今回はその感動したお米の稲刈りを見学させて頂きました。
秋のイメージしかなかった稲刈りでしたが、まさかのお盆前。
そして、当初の目標のその土地のお米をその土地の水で炊くことも達成し、思い出深い1日になりました。

三重県御浜町について、詳しくは下記Webサイトをご覧下さい↓
https://mihama-mie-townpromotion.jp/

Today, we went to see the rice harvesting in Kamiichigi, Mihama, Mie, Japan.
I always thought what is the best way to cook rice.
The answer I found is that rice will be definitely better to be cooked with water, by which rice was grown up.
We met a farmer when we had visited to Mihama in this March.
He gave us rice which he produced in the field we visited today.
The rice he produced was the best taste we ever had.
I was always wondering rice we eat is produced in what kind of place.
It was good that we know the person who produce what we eat in everyday living, how he produces.
We are not sure whether you know how to harvest rice in Japan or not.
See how rice is harvested in Japan at least.

