update content_bodies set title = '【移住を決めた風景 - 凪のあすから聖地巡礼】熊野に移住するキッカケになったジブリみたいな大きなクスノキのある風景｜波田須駅｜田舎暮らし｜熊野｜地方移住｜新鹿｜天女座', description = '移住地探しのためにこの東紀州エリアに来て、一目惚れした風景。
この風景に出会ったから、このエリアに移住を決断できたと思います。
アニメ、凪のあすからの駅のモデルにもなった波田須駅の周辺の街並みは、美しく、今でも聖地巡礼に来られる方も見かける。
ジブリの世界のような風景の中に、勝手にトロロの木と名付けた大きなクスノキ。
大きな木の下に広がる、波田須のリリカルな田舎の日常に魅了されました。

三重県御浜町について、詳しくは下記Webサイトをご覧下さい↓
https://mihama-mie-townpromotion.jp/

よみがえりの地、熊野
熊野にある町、三重県御浜町

熊野は「よみがえりの地」と言われてきました。古来より日本では、人々が生活を営む里に対し、山は神や祖先の霊が宿る神聖な場所である、という考え方があります。中でも熊野は神々が籠る深山の霊場であり、訪れた方は心魂が甦り、新たな気持ちになります。
「人生、出発たびだちの地」

と言われる所以です。また、有史以前から続く自然信仰、熊野修験に代表される山岳宗教、そして神＝仏であるとする神仏習合の信仰形態が相まり、日本固有の宗教観を育む土壌ともなりました。

熊野本宮大社ホームページより引用

無理せず、月に3、4本程度の頻度で動画をアップしていく予定です。
気に入って頂けたら、いいね、コメント、チャンネル登録の方、宜しくお願いします。インスタの方も是非。

Instagram: https://www.instagram.com/rural_life_japan/

その他、情報は下記に載せておきますので、お時間がありましたら是非ご覧ください。

【徐福の宮】
中国人の徐福と波田須の人々との交流の歴史は素晴らしい話です。
是非、その成り立ちをチェックしてみて下さい。
https://www.mikumano.net/meguri/jofukunomiya.html

【徐福茶屋】 
波田須を見渡せる場所にある、地元の有志の方が運営する不定休のカフェ。ここからの風景はお金には変えがたい贅沢です。
https://www.facebook.com/KUMANOHADASU

【凪の家 】
地元の有志の方が運営する新鹿海水浴場の側にあるゲストハウス。
私たちも宿泊しましたが、新鹿の海から昇る朝日は圧巻です。
https://www.naginoie.com/

【御浜町　移住・交流サポートデスク】
御浜町移住に興味のある方は是非。僕らもお世話になりました。
http://mihama-iju.com/

【くまの移住ネット】
熊野市移住に興味のある方は是非。僕らもお世話になりました。
残念ながら、熊野市ではなく、お隣の御浜町に移住しましたが、
親身になってくれた担当者の方のおかげで、移住が実現したといっても過言ではありません。
https://kumanoijunet.jimdofree.com/


2020年7月に東京から三重県御浜町に夫婦で移住しました。
大阪、千葉でそれぞれ生まれ育ち、都会暮らしは十分に堪能。
以前から興味のあった田舎の古民家に移住し田舎暮らし始めました。

Rural Japan #2 Under the Big Tokoro Tree
World of My Neighbor TOTORO

The picture we fell in love with at the first sight when we came to this East Kii Peninsula to find a place to settle.
We think we decided to move to this area because we met this scenery.
I am fascinated by the lyrical landscape where the sea and people live under the big Totoro Tree, which we named.

About Kumano

“Kumano is a feeling - not a form - a manifestation of the Divine Intangibles, a celebration of life''s powerful vitality.
It is a peaceful place in nature to take a moment to reflect on, and reaffirm one''s future direction and meaning of life - a sacred space to open one''s mind, heart soul; all of one''s senses; and let the artificial boundaries and borders of the modern world  disappear - allowing us to contemplate life as one unified humanity on planet earth.
The importance of a pilgrimage to Kumano is not in its completion, but rather what you take home after internalizing your experience” (Kumano Kodo, 2019).

Kumano is the abode of the Gods.
The complicated landscape is considered a sacred site of healing and salvation for a diversity of faiths, and is a symbolic example of Japan''s syncretic religious traditions.

About Mihama Town

Mihama Town is in Mie prefecture, Japan.
Mihama locates in south of Kii peninsula by the sea.
There are many outstanding nature and life which you would understand what Japanese people are really.
We do not have symbolic icons or landmarks in the town.
However, it is a place to purify or relax surrounded by the spiritual and sacred atmosphere.
There are also some Kumano Pilgrimage Routes, Ise Route, and the some fantastic routes within the town.
In this difficult time, you might confront an opportunity for you to consider the meaning of the life.
The place might be able to bring the answer you are searching for.
Please come to visit Mihama.

What kind of life are we searching for?

We are now searching for meaning of life.
We come to see some people those who shows us their meaning of life in Mihama, Kumano.
Most of people moved to Kumano say it has sacred power, 
and the power of Kumano leads us to come living or visiting here.
Once you come to visit Kumano, you would be able to understand what they are saying.
What kind of adventures are waiting for you?


This channel show you Japan countryside living in Mihama, Mie, Japan.

Hope you all are very well even under such heavy rain today.

We moved out to the country side of japan from Tokyo in this July.
Since we came here, it has been a month. We have already touched lots of different value from Tokyo and urban life. It came out been great so far. Well, nobody knows how it goes from now on though.

Hoping you enjoy our channel.
We constantly offer you more videos that are illustrated the country side living of Japan. 
If you like our videos, please leave some comments or subscribe our channel. 
It will definitely make us push forward.

Check the link in my bio for Full Videos.

Cheers!!

Espero que todos estén muy bien incluso bajo una lluvia tan fuerte hoy.

Nos mudamos al campo de Japón desde Tokio en este mes de julio.
Desde que llegamos aquí, ha pasado un mes. Ya hemos tocado muchos valores diferentes de Tokio y la vida urbana. Salió genial hasta ahora. Bueno, nadie sabe cómo será a partir de ahora.

Esperando que disfrutes de nuestro canal.
Constantemente le ofrecemos más videos que ilustran la vida en el campo de Japón.
