#田舎暮らし #地方移住 #凪のあすから' where id = 'JMWkCyKbCQSDD9gGW7dJV';
update content_bodies set title = 'The Landscape That Made Us Decide to Move - Pilgrimage to the Sacred Sites of Nagi no Asukara | A Scene with a Giant Camphor Tree Like a Studio Ghibli Film | Hadasu Station | Rural Living | Kumano | Regional Relocation | Shinjika | Tennyoza', description = 'We came to this East Kii Peninsula area to search for a place to relocate, and we fell in love with this landscape at first sight.
I believe it was this scenery that led us to decide to move to this area.
The streets around Hadasu Station, which served as a model for the anime Nagi no Asukara, are beautiful, and even now, we see visitors coming for pilgrimage.
In a landscape reminiscent of the world of Studio Ghibli, there is a large camphor tree that we have whimsically named the Totoro Tree.
I was captivated by the lyrical rural daily life of Hadasu that unfolds beneath this great tree.

For more information about Mihama Town in Mie Prefecture, please visit the website below:
https://mihama-mie-townpromotion.jp/

The Land of Resurrection, Kumano
The town of Kumano, Mihama Town in Mie Prefecture

Kumano has been referred to as the "Land of Resurrection." Since ancient times in Japan, there has been a belief that while the villages where people live are ordinary, the mountains are sacred places where the spirits of gods and ancestors reside. Among them, Kumano is a spiritual site where deities dwell, and those who visit find their spirits revived and their hearts renewed.
This is why it is said to be the "land of life''s new beginnings."
Additionally, the natural faith that has continued since before recorded history, the mountain religion represented by Kumano Shugendo, and the syncretic belief that gods and Buddhas are one have all contributed to the nurturing of Japan''s unique religious perspective.

Quoted from the Kumano Hongu Taisha website

We plan to upload videos at a frequency of about 3 to 4 times a month without overdoing it.
If you like our content, please give us a thumbs up, leave a comment, and subscribe to our channel. We would also appreciate it if you could check out our Instagram.

