For more information, please see below, and if you have time, do take a look.

【Jofuku no Miya】
The history of the exchange between the Chinese Jofuku and the people of Hadasu is a wonderful story.
Please check out its origins.
https://www.mikumano.net/meguri/jofukunomiya.html

【Jofuku Chaya】
A café run by local volunteers located in a place overlooking Hadasu. The view from here is an invaluable luxury.
https://www.facebook.com/KUMANOHADASU

【Nagi no Ie】
A guesthouse located near Shinjika Beach, operated by local volunteers.
We also stayed here, and the sunrise over the sea at Shinjika is breathtaking.
https://www.naginoie.com/

【Mihama Town Relocation and Exchange Support Desk】
If you are interested in relocating to Mihama Town, please do reach out. We received great support here.
http://mihama-iju.com/

【Kumano Relocation Network】
If you are interested in relocating to Kumano City, please do check it out. We also received great support here.
Unfortunately, we relocated to the neighboring Mihama Town instead of Kumano City, but thanks to the dedicated staff, our move became a reality.
https://kumanoijunet.jimdofree.com/

