update content_bodies set title = '【簡体字】Royal Food of Japan MIKETSUKUNI～Delicacies cherished since ancient times～', description = '福井县 若狭・三重县 志摩・兵库县 淡路岛
这里是享有　“御食国”美誉之地　约1200年前起
一直是向朝廷　京都进奉食材的　美食宝库
共赴一场历经漫长岁月　细细磨砺的
和食文化　与皇家美食的邂逅之旅
细品历史珍藏的美味。Royal Food of Japan　御食国　MIKETSUKUNI

00:00 Introduction
