This is a place renowned as the "Miketsukuni," a treasure trove of gourmet food that has been supplying ingredients to the imperial court in Kyoto since about 1200 years ago.
Join us on a journey to encounter the refined culture of Japanese cuisine and royal delicacies, honed over a long period of time.
Savor the deliciousness treasured throughout history. Royal Food of Japan, Miketsukuni

