update content_bodies set title = 'The Expo and Beyond ! Travel All Around KANSAI, Japan. (JP, short)', description = '関西には、長い歴史によって育まれた文化や、人々の営み、脈々といのちを紡いできた地域性や持続可能性があります。万博と一緒に、関西への旅を一歩踏み出してみませんか。あなたのいのち輝かせる旅へ、ここ関西で。' where id = 'egFK9xo4Fzjx7-6-lsVmk';
update content_bodies set title = 'The Expo and Beyond ! Travel All Around KANSAI, Japan. (JP, short)', description = 'Kansai is home to a culture nurtured by a long history, the activities of its people, and a regional character that has woven together life and sustainability over the years. Why not take a step towards a journey to Kansai along with the Expo? Embark on a journey that will make your life shine here in Kansai.' where id = 'iJ4ne8ek4WfEGYfYUPy6G';
update content_bodies set title = 'The World EXPO and Beyond ! Travel All Around KANSAI, Japan.', description = '万博で出会う様々な技術革新や未来社会のデザインは、私達一人ひとりが主体となって「これから」のよりよい社会を考える機会になるのではないでしょうか。新しい体験を通して感性を磨き、これまで持っていなかった視点を得ることにつながります。関西には、長い歴史によって育まれた文化や、人々の営み、脈々といのちを紡いできた地域性や持続可能性があります。万博と一緒に、関西への旅を一歩踏み出してみませんか。あなたのいのち輝かせる旅へ、ここ関西で。

万博プラス関西観光スペシャルサイト：https://www.the-kansai-guide.com/ja/expo2025-plus/

万博公式サイト：https://www.expo2025.or.jp/' where id = 'o85DLv18DM8yF__vL8qaO';
update content_bodies set title = 'The World EXPO and Beyond ! Travel All Around KANSAI, Japan.', description = 'The various technological innovations and designs for future societies encountered at the Expo may provide each of us with an opportunity to think about a better society for ''the future.''
Through new experiences, we can refine our sensibilities and gain perspectives we have not had before.
Kansai is rich in culture nurtured by a long history, the activities of its people, and the regional characteristics and sustainability that have woven life through the ages.
Why not take a step towards a journey to Kansai along with the Expo?
Here in Kansai, embark on a journey that will make your life shine.' where id = 'lJqEj6lAb6HT_g2NRgOtW';
update content_bodies set title = 'Going for Sushi ／ お寿司屋編', description = 'Learn more about KANSAI： https://www.the-kansai-guide.com/en/
Facebook： https://www.facebook.com/truekansai/
Instagram：https://www.instagram.com/realjapankansai/' where id = 'kYpgkqctf9jNkuDvrxaVo';
