Facebook： https://www.facebook.com/truekansai/
Instagram：https://www.instagram.com/realjapankansai/' where id = 'cWgb4Y-bNBRg2LjpyBITK';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan: J trailer2/QR', description = 'かつて都が存在した関西には、和食、茶道、古典芸能、工芸、禅など数えきれないほどの日本文化の源流があり、今もそれらを受け継ぐ方がいます。そんな関西が誇る“宝”に出会う旅へと、今から皆さまをお連れします。あるひとつの道を極めた一流の方が、特別な空間でお届けする“体験”を、動画ではオンラインで疑似体験をすることができます。疑似体験を超えた実際の体験はここ関西で。
https://www.the-kansai-guide.com/ja/exclusive-expeditions/

https://www.youtube.com/channel/UCBOyUMbb7JVSNVzV-lmLmPA/featured' where id = 'vGFbx7MEYSex_fGIbFsCi';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan: J trailer2/QR', description = 'In Kansai, where the capital once existed, there are countless sources of Japanese culture such as washoku (Japanese cuisine), tea ceremony, classical performing arts, crafts, and Zen, and there are still those who inherit them today. We will take you on a journey to encounter the ''treasures'' that Kansai proudly boasts. You can experience a ''special experience'' delivered by a top expert who has mastered a particular path in a special space, and in the video, you can have a simulated experience online. The actual experience that goes beyond the simulation awaits you here in Kansai.
https://www.the-kansai-guide.com/ja/exclusive-expeditions/

https://www.youtube.com/channel/UCBOyUMbb7JVSNVzV-lmLmPA/featured' where id = 'qk0MrASe93MZQwHj1WIkA';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Wakayama [4K]簡体字', description = '#熊野本宫大社 #熊野古道 #世界遗产 #文化体验 #熊野 #和歌山 #关西

【宮司 九鬼家隆 × 熊野本宫大社】
纪伊山地有着神秘的群山与苍郁的森林。位在山林深处的熊野，是知名的日本三大灵场之一，也是神圣之地。而连结居于主要地位的熊野本宫大社与另外两座神社的熊野古道，自古以来就被人们视为日本最重要的参拜道路。从日本创始时期就孕育了许多传说的熊野是知名的「重生圣地」，至今仍有许多参拜者慕名而来。

本影片中所介绍的文化体验的详细资讯：
https://www.the-kansai-guide.com/en/article/item/20036/

了解这个文化体验的行程安排：
https://www.the-kansai-guide.com/en/article/item/20037/' where id = 'prxfz2egr8JTP-RvVe5E3';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Wakayama [4K] Simplified Chinese', description = '#Kumano Hongu Taisha #Kumano Kodo #World Heritage #Cultural Experience #Kumano #Wakayama #Kansai

【Chief Priest Kuki Ietaka × Kumano Hongu Taisha】
The Kii Mountain Range is home to mysterious mountains and lush forests. Located deep within the mountains, Kumano is one of Japan''s three major sacred sites and a holy place. The Kumano Kodo, which connects the prominent Kumano Hongu Taisha with two other shrines, has been regarded as Japan''s most important pilgrimage route since ancient times. Kumano, known as a ' where id = 'EBhkzMN2ZrHkJvhBQ28Iz';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Wakayama [4K]繁体字', description = '#熊野本宮大社 #熊野古道 #世界遺產 #文化體驗 #熊野 #和歌山 #關西

【宮司 九鬼家隆　× 熊野本宮大社】
紀伊山地有著神秘的群山與蒼鬱的森林。位在山林深處的熊野，是知名的日本三大靈場之一，也是神聖之地。而連結居於主要地位的熊野本宮大社與另外兩座神社的熊野古道，自古以來就被人們視為日本最重要的參拜道路。從日本創始時期就孕育了許多傳說的熊野是知名的「重生聖地」，至今仍有許多參拜者慕名而來。

本影片中所介紹的文化體驗的詳細資訊：
https://www.the-kansai-guide.com/en/article/item/20036/

了解此文化體驗的行程安排：
https://www.the-kansai-guide.com/en/article/item/20037/' where id = '_E0di_NmTuFVrjxYqOcpj';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Wakayama [4K] Traditional Chinese', description = '#Kumano Hongu Taisha #Kumano Kodo #World Heritage #Cultural Experience #Kumano #Wakayama #Kansai

