【宮司 九鬼家隆　×　熊野本宮大社】 

神秘的な山々と深い森が広がる紀伊山地。その奥深くに位置する熊野は、日本三大霊場のひとつとして知られる神聖な地域であり、熊野本宮大社と2つの社をつなぐ熊野古道は、日本でもっとも重要な参詣道として、古の時代より現在、そしてこれから未来へと人々を受け入れる「道」となるだろう。日本の黎明期から数々の伝説を生んできた熊野は、“甦りの聖地“として知られ、今でも多くの参詣者が訪れている。

