【五條良知 (管長) × 金峯山寺】
長居深山透過嚴格修行以悟道的「修驗道」，是日本自古以來即有的山岳信仰。佇立於紀伊山地吉野山山腰的金峯山寺，是由役行者在７世紀所創建的修驗道中心道場，並且保存了許多有形文化資產。管長五條良知的重要工作之一，就是守護本尊藏王權現等文化遺產，讓它們未來也得以一直留傳下去。

