Shugendo, a path to enlightenment through strict training in the deep mountains, is a mountain faith that has existed in Japan since ancient times. Kimpusenji, located on the slopes of Yoshino Mountain in the Kii Mountain Range, is a center of Shugendo established by En no Gyoja in the 7th century and preserves many tangible cultural assets. One of Abbot Gojō Ryōchi''s important tasks is to protect cultural heritage such as the principal image, Zōō Gongen, ensuring that they can be passed down in the future.

