【五條良知（管長）×金峯山寺】 
山に籠っておこなう厳しい修行により悟りを得るという日本古来の山岳信仰、「修験道」。紀伊山地、吉野山の中腹に佇む金峯山寺は、7世紀に役行者によって開かれた修験道の根本道場であり、数多くの有形文化財が収蔵されている場所だ。本尊の蔵王権現をはじめとするこれらの文化遺産を守り、未来へとつないでいくことは、管長である五條良知氏の大切な仕事のひとつとなっている。

