【Ryochi Gojo (Abbot) × Kinpusenji】
Shugendo, the ancient Japanese mountain faith, is a rigorous practice of ascetic training conducted in the mountains to attain enlightenment. Kinpusenji, located on the slopes of Yoshino Mountain in the Kii Mountain Range, is the fundamental training hall of Shugendo, established in the 7th century by En no Gyoja, and houses numerous tangible cultural properties. One of the important tasks of Abbot Ryochi Gojo is to protect these cultural heritage sites, including the principal deity Zao Gongen, and to pass them on to the future.

