update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Hyogo[4K]繁体字', description = '#薪能 #能 #天空之杜 #日本文化 #伊勢神宮 #文化體驗 #北野天滿神社 #兵庫 #關西

【薪能　觀世流仕手方能樂師　上田宜照　× 北野天滿神社】

在能夠一覽神戶市區風光的北野坂上，有一座歷史悠久、被稱為「天空之森林」的神社。　就是供奉著學問之神菅原道真公，創建於西元1180年的北野天滿神社。好幾個世紀以來，環繞著怡人景色的北野天滿神社拜殿持續上演著獻給神明的能劇，同時也深受人們喜愛。' where id = 'CzPikORaQ5xGcNnPS7d-0';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Hyogo[4K] Traditional Chinese', description = '#薪能 #能 #天空之杜 #日本文化 #伊勢神宮 #文化體驗 #北野天滿神社 #兵庫 #關西

【薪能　觀世流仕手方能樂師　上田宜照　× 北野天滿神社】

At the top of Kitano-zaka, where you can enjoy a panoramic view of Kobe city, there is a historic shrine known as the ''Forest of the Sky.'' This is the Kitano Tenmangu Shrine, dedicated to Sugawara no Michizane, the god of learning, and established in 1180 AD. For several centuries, the Kitano Tenmangu Shrine, surrounded by pleasant scenery, has continuously performed Noh plays dedicated to the deities, and it is also beloved by the people.' where id = 'h7DT6vLKZhIwkn04sG-9K';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Osaka[4K]簡体字', description = '#能 #日本文化 #人间国宝 #文化体验 #大阪天满宫 #大阪 #关西

【观世流仕手方能乐师 上野朝义*、上野朝彦 (*重要无形文化资产) × 大阪天满宫】
属于世上最古老舞台艺术之一的「能」，是始于14世纪的日本传统艺能。特色是充满神秘色彩的剧情、具象征意义的面具、华美绚丽的装束以及经过形式化的动作等。在大阪天满宫庄严的本殿表演演舞的，是掌管朝阳会馆的上野朝义。他和2名弟弟都是获得重要无形文化资产保持者认证的能乐师。' where id = '5INzk9HxmxWg3RvqfKWW3';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Osaka[4K] Simplified Chinese', description = '#Noh #JapaneseCulture #LivingNationalTreasure #CulturalExperience #OsakaTenmangu #Osaka #Kansai

【Kanze School Noh Performer Ueno Asahi*, Ueno Asahiko (*Important Intangible Cultural Asset) × Osaka Tenmangu】
Noh, one of the oldest performing arts in the world, is a traditional Japanese art that began in the 14th century. It is characterized by its mysterious plots, symbolic masks, splendid costumes, and formalized movements. Performing at the solemn main hall of Osaka Tenmangu is Ueno Asahi, who manages the Asahi Hall. He and his two brothers are certified Noh performers recognized as important intangible cultural asset holders.' where id = 'CnhgVohfLWZvpkYAfH08G';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Osaka[4K]繁体字', description = '#能 #日本文化 #人間國宝 #文化體驗 #大阪天滿宮 #大阪 #關西 

【觀世流仕手方能樂師 上野朝義*、上野朝彥 (*重要無形文化資產) × 大阪天滿宮】
屬於世上最古老舞台藝術之一的「能」，是始於14世紀的日本傳統藝能。特色是充滿神秘色彩的劇情、具象徵意義的面具、華美絢麗的裝束以及經過形式化的動作等。在大阪天滿宮莊嚴的本殿表演演舞的，是掌管朝陽會館的上野朝義。他和2名弟弟都是獲得重要無形文化資產保持者認證的能樂師。' where id = '__e3vHjWR1pmtVfT3IOSh';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Osaka[4K] Traditional Chinese', description = '#Noh #JapaneseCulture #LivingNationalTreasure #CulturalExperience #OsakaTenmangu #Osaka #Kansai

【Kanze School Noh Performer Asai Ueno*, Asai Ueno (*Important Intangible Cultural Asset) × Osaka Tenmangu】
Noh, one of the oldest performing arts in the world, is a traditional Japanese art that began in the 14th century. It is characterized by its mysterious plots, symbolic masks, splendid costumes, and formalized movements. Performing at the solemn main hall of Osaka Tenmangu is Asai Ueno, who manages the Asahi Hall. He and his two brothers are certified Noh performers recognized as important intangible cultural asset holders.' where id = 'LIh58JanYq14zVH1BrLaL';
