【薪能 × 北野天満神社】
神戸の街を一望できる北野坂の上に、「天空の社」と呼ばれる由緒正しき神社がある。
学問の神 菅原道真公を御祭神として、1180年に創建された北野天満神社だ。
素晴らしい眺望を背景にした北野天満神社の拝殿では、数世紀にわたって能が奉納され、人々を魅了してきた。


