【Fire Noh × Kitano Tenmangu Shrine】
Atop Kitano-zaka, which offers a panoramic view of Kobe, stands a historic shrine known as the ''Sky Shrine.''
Founded in 1180, Kitano Tenmangu Shrine enshrines Sugawara no Michizane, the deity of learning.
For centuries, Noh performances have been dedicated at the hall of Kitano Tenmangu Shrine, captivating audiences against a backdrop of stunning views.

