update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Tottori[4K]簡体字', description = '#白磁 #日本文化 #人间国宝 #石谷家住宅 #文化体验 #智头町 #鸟取 #关西

【白磁 前田昭博（人间国宝）× 石谷家住宅】
鸟取县是日本人口最少的县。许多艺术家认为这里清幽的环境最适合创作。 2013年获得重要无形文化资产保持者认证的白磁作家前田昭博也不例外。柔和的自然光形成的阴影，让纯白洁净的磁器更有存在感。而深受前田喜爱的展示场所，就是位在鸟取县智头町的石谷家住宅。建筑群的配置以日本庭园为中心，是近代和风建筑的知名杰作，也被列为国家重要文化资产。' where id = '4POeuQGYDpbTZMeyi1ckQ';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Tottori[4K] Simplified Chinese', description = '#WhitePorcelain #JapaneseCulture #LivingNationalTreasure #IshiyaHouse #CulturalExperience #ChizuTown #Tottori #Kansai

【White Porcelain Akihiro Maeda (Living National Treasure) × Ishiya House】
Tottori Prefecture is the least populated prefecture in Japan. Many artists believe that the serene environment here is most suitable for creation. Akihiro Maeda, a white porcelain artist who was certified as an important intangible cultural asset holder in 2013, is no exception. The shadows formed by the soft natural light give the pure white porcelain a stronger presence. The exhibition venue that Maeda loves is the Ishiya House located in Chizu Town, Tottori Prefecture. The layout of the buildings is centered around a Japanese garden, making it a renowned masterpiece of modern Japanese architecture, and it is also designated as an important cultural asset of the country.' where id = 'haVfawGPDZtohSRORGLlL';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Shiga[4K]簡体字', description = '#三井寺 #日本文化 #琵琶湖 #文化体验 #国宝 #滋贺 #关西

【福家俊彦（长吏）× 三井寺】
三井寺位于比睿山山麓，面对着琵琶湖，是平安时代朝廷做为祈愿所的四大寺院一。建于寺院区域内的40多栋建筑物里，至今仍保存了超过650件的国宝与重要文化资产。在悠长而严峻 的历史中持续守护着这些文化资产长达1300年，对于三井寺的长吏和僧侣们来说，可谓是赌上性命的重责大任。' where id = 'Tb51fcNCSV9NszcRKsfwE';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Shiga[4K] Simplified Chinese', description = '#Mitsui Temple #Japanese Culture #Lake Biwa #Cultural Experience #National Treasure #Shiga #Kansai

【Toshihiko Fukuya (Chief Priest) × Mitsui Temple】
Mitsui Temple is located at the foot of Mount Hiei, facing Lake Biwa, and is one of the four major temples established by the Heian period court as a place of prayer. Among the more than 40 buildings within the temple area, over 650 national treasures and important cultural assets are still preserved today. For 1300 years, these cultural assets have been continuously protected through a long and severe history, making it a heavy responsibility for the chief priests and monks of Mitsui Temple, one that they have staked their lives on.' where id = 'b5lRKntD7UFnnBfLbO-wP';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Tottori[4K]繁体字', description = '#白磁 #日本文化 #人間國寶 #石谷家住宅 #文化體驗 #智頭町 #鳥取 #關西

【白磁 前田昭博（人間國寶）× 石谷家住宅】
鳥取縣是日本人口最少的縣。許多藝術家認為這裡清幽的環境最適合創作。2013年獲得重要無形文化資產保持者認證的白磁作家前田昭博也不例外。柔和的自然光形成的陰影，讓純白潔淨的磁器更有存在感。而深受前田喜愛的展示場所，就是位在鳥取縣智頭町的石谷家住宅。建築群的配置以日本庭園為中心，是近代和風建築的知名傑作，也被列為國家重要文化資產。' where id = '7eLMNT4RfJYC7J4r3pZK1';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Tottori[4K] Traditional Chinese', description = '#WhitePorcelain #JapaneseCulture #LivingNationalTreasure #IshiyaHouse #CulturalExperience #ChizuTown #Tottori #Kansai

【White Porcelain Akihiro Maeda (Living National Treasure) × Ishiya House】
Tottori Prefecture is the least populated prefecture in Japan. Many artists believe that the serene environment here is most suitable for creation. Akihiro Maeda, a white porcelain artist who received certification as an important intangible cultural asset holder in 2013, is no exception. The shadows formed by the soft natural light give the pure white porcelain a stronger presence. The exhibition space that Maeda loves is the Ishiya House located in Chizu Town, Tottori Prefecture. The layout of the buildings is centered around a Japanese garden, making it a renowned masterpiece of modern Japanese architecture, and it is also designated as an important cultural asset of the country.' where id = 'X4nkMb3A3qIzI-sASstGv';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Shiga[4K]繁体字', description = '#三井寺 #日本文化 #琵琶湖 #文化體驗 #國寶 #滋賀 #關西

【福家俊彥（長吏）× 三井寺】
三井寺位於比叡山山麓，面對著琵琶湖，是平安時代朝廷做為祈願所的四大寺院一。建於寺院區域內的40多棟建築物裡，至今仍保存了超過650件的國寶與重要文化資產。在悠長而嚴峻 的歷史中持續守護著這些文化資產長達1300年，對於三井寺的長吏和僧侶們來說，可謂是賭上性命的重責大任。' where id = 'IzjMW-Zyfi67pMCwDkCkF';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Shiga[4K] Traditional Chinese', description = '#MitsuiTemple #JapaneseCulture #LakeBiwa #CulturalExperience #NationalTreasure #Shiga #Kansai

【Toshihiko Fukuya (Chief Priest) × Mitsui Temple】
Mitsui Temple is located at the foot of Mount Hiei, facing Lake Biwa, and is one of the four major temples established by the Heian period court as a place of prayer. Among the more than 40 buildings within the temple complex, over 650 national treasures and important cultural assets are still preserved today. For 1300 years, these cultural assets have been continuously protected through a long and severe history, making it a heavy responsibility for the chief priests and monks of Mitsui Temple, who have staked their lives on this duty.' where id = 'ODo2zCuHeCkCXTka9uH3P';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Hyogo[4K]簡体字', description = '#薪能 #能 #天空之杜 #日本文化 #伊势神宫 #文化体验 #北野天满神社 #兵库 #关西

【薪能　观世流仕手方能乐师　上田宜照　× 北野天满神社】
在能够一览神户市区风光的北野坂上，有一座历史悠久、被称为「天空之森林」的神社。　就是供奉着学问之神菅原道真公，创建于西元1180年的北野天满神社。好几个世纪以来，环绕着怡人景色的北野天满神社拜殿持续上演着献给神明的能剧，同时也深受人们喜爱。' where id = 'fccLjf4NG43phCqJUJjxe';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Hyogo[4K] Simplified Chinese', description = '#薪能 #能 #天空之杜 #日本文化 #伊势神宫 #文化体验 #北野天满神社 #兵库 #关西

【薪能　观世流仕手方能乐师　上田宜照　× 北野天满神社】
在能够一览神户市区风光的北野坂上，有一座历史悠久、被称为「天空之森林」的神社。　就是供奉着学问之神菅原道真公，创建于西元1180年的北野天满神社。好几个世纪以来，环绕着怡人景色的北野天满神社拜殿持续上演着献给神明的能剧，同时也深受人们喜爱。' where id = 'qoh-aq8mBtbdCDyGmxlHn';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Tokushima[4K]簡体字', description = '#人形净琉璃 #日本文化 #农村舞台 #文化体验 #德岛 #关西
【阿波人形净琉璃 太夫 竹本友和嘉（重要无形文化财）× 犬饲农村舞台（重要有形民俗文化财）】
德岛位于四国的东面，保留的农村舞台数量是日本最多的。这是在江户时代后期，当地居民为了感谢五谷丰收而搭建的户外舞台。在这座舞台上演的是一直以来受到当地居民喜爱的阿波人形净琉璃。这是自往昔传承至今，当地具代表性的传统艺能。

本影片中所介绍的文化体验的详细资讯：
https://www.the-kansai-guide.com/en/article/item/20019/

了解这个文化体验的行程安排：
https://www.the-kansai-guide.com/en/exclusive-expeditions/course/tokushima/' where id = '0pXja4H8ZRG2AxyYh7wiW';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Tokushima[4K] Simplified Chinese', description = '#Awa Puppet Theater #Japanese Culture #Rural Stage #Cultural Experience #Tokushima #Kansai
【Awa Puppet Theater Master Tomokazu Takemoto (Important Intangible Cultural Asset) × Inukai Rural Stage (Important Tangible Folk Cultural Asset)】
Tokushima, located on the eastern side of Shikoku, has the highest number of preserved rural stages in Japan. This outdoor stage was built by local residents in the late Edo period to express gratitude for a bountiful harvest. The Awa Puppet Theater, which has been loved by local residents for generations, is performed on this stage. It is a representative traditional art form of the area that has been passed down through the ages.

Detailed information about the cultural experience introduced in this video:
https://www.the-kansai-guide.com/en/article/item/20019/

Learn about the itinerary for this cultural experience:
https://www.the-kansai-guide.com/en/exclusive-expeditions/course/tokushima/' where id = 'pjtXjnWbiWffYdDbmxz9J';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan -Kyoto[4K]簡体字', description = '#茶道 #日本文化 #平安神宫 #文化体验 #古田织部 #京都 #关西
【茶道 织部流扶桑派  尾崎米柏（第四代家元）× 平安神宫 尚美馆（国家指定名胜）】
西元16世纪时，千利休将日本的各种文化融合后赋予茶道新的定义，并将茶道升华为日本的美学。古田织部是利休门下的七名弟子之一。他也创立了自己的流派，却数度被时代的洪流所淹没，最后织部派演变为「御法度流仪」。

本影片中所介绍的文化体验的详细资讯：
https://www.the-kansai-guide.com/en/article/item/20017/

