In the 16th century, Sen no Rikyū redefined the tea ceremony by integrating various aspects of Japanese culture, elevating it to an aesthetic form of Japan. Furuta Oribe was one of the seven disciples of Rikyū. He established his own school, but was often submerged by the tides of time, ultimately leading to the Oribe school evolving into the ' where id = 'nq9ruZaOwdBXZTcsAy6sQ';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan -Mie[4K]簡体字', description = '#伊势大神乐 #日本文化 #伊势神宫 #文化体验 #神楽 #三重 #关西
【伊势大神乐 山本勘太夫社中（重要无形名俗文化财）× 宝日馆（重要文化财）】
古时候老百姓的心愿，就是一生中能够前往伊势神宫参拜一次。而山本勘太夫这样的神乐师，就是为了那些无法前往伊势参拜的人们巡回全国，祝祷五谷丰收、无灾无难。

