update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan -Mie[4K] Simplified Chinese', description = '#Ise Grand Kagura #Japanese Culture #Ise Jingu #Cultural Experience #Kagura #Mie #Kansai
【Ise Grand Kagura Yamamoto Kanta-ryu (Important Intangible Folk Cultural Asset) × Houjikan (Important Cultural Asset)】
In ancient times, the common people''s wish was to visit Ise Jingu at least once in their lifetime. Kagura performers like Yamamoto Kanta-ryu travel across the country for those who cannot visit Ise, praying for a bountiful harvest and safety from disasters.

