【越前和纸 岩野市兵卫（人间国宝）×　岩野市兵卫氏工房】

福井县越前地方至今仍延续着1500年前的传统制法，以手工制造和纸。其中，越前和纸职人的第9代岩野市兵卫所漉的纸被世界各地誉为是最好的和纸。

