update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Fukui[4K] Simplified Chinese', description = '#Echizen Washi #Japanese Culture #Living National Treasure #Cultural Experience #Paper Making #Fukui #Kansai
【Echizen Washi Iwano Ichibei (Living National Treasure) × Iwano Ichibei''s Workshop】

Fukui Prefecture''s Echizen region continues the traditional paper-making method that has been around for 1500 years, producing washi by hand. Among them, the paper made by the 9th generation Echizen washi craftsman Iwano Ichibei is renowned worldwide as the best washi.

