【茶道 織部流扶桑派 尾﨑米栢（四代目家元）× 平安神宮 尚美館（国指定名勝）】
16世紀、さまざまな日本文化を融合して茶道を再定義、日本の美学へと昇華させた千利休。その利休の七人弟子のひとり、古田織部も独自の流派を確立するが、数奇な運命に翻弄され、織部流は御法度流儀として知られるようになる。

