update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Kyoto [4K]', description = '#TeaCeremony #JapaneseCulture #HeianShrine #CulturalExperience #FurutaOribe #Kyoto #Kansai

【Tea Ceremony Oribe School Fuso Branch, Yoshikawa Komei (4th Generation Headmaster) × Heian Shrine Naobikan (Nationally Designated Scenic Spot)】
In the 16th century, Sen no Rikyū redefined the tea ceremony by merging various aspects of Japanese culture, elevating it to the realm of Japanese aesthetics. One of Rikyū''s seven disciples, Furuta Oribe, also established his own unique school, but was swept away by a strange fate, leading the Oribe school to be known as the forbidden style.

