update content_bodies set title = 'Spiritual KANSAI , Onsen 簡体字', description = 'Feel across your entire body the blessings of a culture that has remained firm for more than a thousand years – hot springs, local cuisine, and Japanese sake – finding release from the exhaustion of everyday life and providing energy for tomorrow while relaxing and refreshing both body and mind.

more about Spiritual KANSAI (Scheduled to be released on Dec. 28th)
