In a land built on volcanic activity, and pure subterranean waters, the culture of the Onsen, hot springs, and traditional Ryokan have been enjoyed for over a thousand years.  
The hot, natural waters, and the calm, surrounding atmosphere, combined with traditional Japanese hospitality, the finest of sake and local cuisine, creates a spiritual release for the body and soul.
Kansai, Japan’s spiritual region. 
Kansai, Japan.

受惠于丰沛的地下水源，肥沃滋养着大地。
孕育超过千年历史的温泉文化，
与自然融为一体的传统旅馆。
浸入温泉，任由暖意洗涤疗愈心灵，
品尝清澈伏流水酿造的清酒，
当地精选乡土佳肴尽享酒意微醺。
在宾至如归的待客之道中，彻底释放身心灵。
关西，日本的灵魂之心。
关西，日本。


The KANSAI Guide: https://www.the-kansai-guide.com/en/
