If we reconsider our moral compass, we can rise to a higher level.   Jin means humanity, charity, emotions ….Gi, Honesty, morality, sincerity …Rei gratitude,…..Chi, wisdom, understanding…. Shin, the strength to believe,..Chuu, loyalty, fidelity….
This is the philosophy of Bushido, found in Kansai, 
Japan’s spiritual region. Kansai, Japan.

當我們誠實面對自己，審視自我道德心時，人格也將隨之昇華。
「仁」，惻隱之心。
「義」，誠實公正。
「禮」，謙讓尊重。
「智」，明辨是非。
「信」，誠信守諾。
「忠」，忠誠真心。
迎接武士道精神的洗禮。
關西，日本的靈魂之心。
