從遠古時代傳承至今，
各式祭典、傳統藝能與生活方式，
人類信仰與意識的匯集，我們稱之為「文化」。
有時是非具象的形態，卻能觸碰內心深處，感受它散發出的無窮力量。
向先人致敬，感恩大地無私的藴育。
邂逅悠久的日本文化。
關西，日本的靈魂之心。
關西，日本。

大昔から受け継いできたこと。
祭り、伝統芸能、生活様式。
人間の精神活動の全て、それを私たちは「文化」と呼んでいる。
それは時として目に見えない。
しかし感じることができる。
先人たちへの祈り、そして地域の恵みへの感謝。
悠久の日本文化に出会える地。
KANSAI, the Spiritual region in Japan.
