various festivals, traditional arts, and ways of life,
the gathering of human beliefs and consciousness, we call it "culture."
Sometimes it takes an abstract form,
yet it can touch the depths of the heart, feeling the infinite power it radiates.
Paying homage to our ancestors, grateful for the earth''s selfless nurturing.
Encounter the long-standing Japanese culture.
Kansai, the spiritual heart of Japan.
