update content_bodies set title = 'Spiritual KANSAI , Wabi Sabi   繁体字', description = 'Visit a beautiful Japanese garden, dress in a formal kimono, and try preparing some tea; or perhaps visit one of the villages of old-and-simple homes that can still be found across Kansai. Finding order and respect among simple things, and a pure beauty in something old - these are the moments that you feel “wabi-sabi.”

