: https://www.the-kansai-guide.com/en/index/spiritual/

There is nothing more harmonious than the atmosphere of old Japan. 
Places of tradition, 
of tranquility, 
innocence, 
honesty and integrity, 
simplicity, 
purity, 
and a respect for nature and for one another. 
Where the traditional Japanese aesthetics of Wabi Sabi, 
perfection in imperfection can be truly experienced.  
Kansai, Japan’s spiritual region. 
Kansai, Japan.

純樸簡素的古民家，清澈純淨的流水滋潤了庭園。
賓主間的敬意與片刻的靜謐平和。
和諧
尊敬
純凈
寧靜
「和敬清寂」的茶道精神。
感受萬物哀愁與悵然的日式美學。
關西，日本的靈魂之心。
關西，日本。

