update content_bodies set title = 'Spiritual KANSAI , Pilgrimage  簡体字', description = 'If you choose to walk the entire route - which takes a number of days - you can hope to find harmony with nature and a new respect for those who have come before you. Then you may connect with your inner self, discovering a new life and new values, and being reborn in nature. This is the kind of spiritual experience that awaits you in the mountains.

