update content_bodies set title = 'Spiritual KANSAI , Meditation   繁体字', description = 'In a large temple, with a beautiful garden, rich history, and a gentle breeze, adopt the special seating position for Zen meditation; hold a writing brush, face the Japanese paper, and express what lies within your heart by writing; then have a delicious meal that brings you the blessings of nature. Learn about the spiritual culture of Japan while rediscovering your own perfect balance between body and mind.

