What does it take to detach yourself from the ways of the world, to become one with the wind, the waters, and nature? 
To find yourself, within yourself,…where the senses, Sight, sound, touch, taste and smell, are re-awakened.  
One becomes what one should be….Zen.  
Reconnect with your heart, and soul, in Kansai, 
Japan’s spiritual region.
Kansai, Japan.

微風輕拂，鳥兒輕啼，潺潺溪流，
