update content_bodies set title = '松之山サステナブル・ダイニングin美人林2023', description = 'TAKAZAWA & TELMONT
Matsunoyama Sustainable Dining in 美人林 2023
https://www.matsunoyama-onsen.com/2023/09/01/1-45/

持続可能性。そのお手本が日本の里山には、いまもなお残されています。里山の営みは、容赦なく降り続く豪雪によって、幾度となく寸断され、脅かされ、それでもまた立ちあがって、自然と共存しながら受け継がれてきました。その壮大なる里山ストーリ―を、世界の「TAKAZAWA」が料理で再構築する松之山ダイニング。「TAKAZAWA」によって語られる里山ストーリー5回目の夏は、雪国のサスティナブルな環境に賛同するフランス・シャンパーニュの「TELMONT」に特別協賛していただきました。

ニセコ「TAKAZAWA」高澤義明シェフ / 西麻布「Ma Cuisine(マ・キュイジーヌ)」 / 池尻綾介シェフ / 世田谷「Signifiant Signifie（シニフィアン・シニフィエ）志賀勝栄シェフ / 新富町「Coulis(クーリ)折笠龍馬シェフ / 酒の宿玉城屋 栗山昭シェフ / ひなの宿ちとせ 柳政道シェフ

Special thanks ：ひなの宿ちとせ / TAKAZAWA / Ma Cuisine / Signifiant Signifié / Coulis / 酒の宿玉城屋 / TELMONT / 雪国観光圏 / 松之山温泉合同会社まんま / 十日町市観光協会' where id = '4eRjcCeJvV2OzZ-kuRhfm';
update content_bodies set title = 'Matsunoyama Sustainable Dining in Bijinbayashi 2023', description = 'TAKAZAWA & TELMONT
Matsunoyama Sustainable Dining in Bijinbayashi 2023
https://www.matsunoyama-onsen.com/2023/09/01/1-45/

Sustainability. An example of this still remains in Japan''s satoyama. The activities of the satoyama have been repeatedly interrupted and threatened by the relentless heavy snowfall, yet they have risen again, inheriting the tradition while coexisting with nature. Matsunoyama Dining reconstructs this grand satoyama story through cuisine, presented by the world-renowned ''TAKAZAWA.'' This summer marks the fifth time the satoyama story is told by ''TAKAZAWA,'' with special sponsorship from ''TELMONT'' of France, which supports the sustainable environment of the snow country.

Niseko ''TAKAZAWA'' Chef Yoshitaka Takazawa / Nishiazabu ''Ma Cuisine'' / Chef Ayasuke Ikejir / Setagaya ''Signifiant Signifie'' Chef Katsuaki Shiga / Shintomi Town ''Coulis'' Chef Ryoma Orikasa / Sake Inn Tamakiya Chef Akira Kuriyama / Hinano-yado Chitose Chef Masamichi Yanagi

Special thanks: Hinano-yado Chitose / TAKAZAWA / Ma Cuisine / Signifiant Signifié / Coulis / Sake Inn Tamakiya / TELMONT / Yukiguni Tourism Area / Matsunoyama Onsen LLC Manma / Tokamachi City Tourism Association' where id = '4HJKQP84NQu_CO16HjfkH';
update content_bodies set title = '雪国観光圏があなただけの旅をご提案します', description = 'あなたは旅になにを求めますか？
自らの見識を広げる経験。地域社会や環境への配慮。本来の自分に戻る時間。旅に求めるものは、きっと人それぞれ。
お気軽に雪国観光圏に相談してみてください。
雪国の自然や文化に根ざした本物の体験交流のなかから、あなただけの旅を組み立てて、ご提案します。

http://snow-country.jp/' where id = 'LMr9DiGjeKT5lr-pJPZyw';
update content_bodies set title = 'The Snow Country Tourism Area Proposes a Journey Just for You', description = 'What do you seek in a journey?
Experiences that broaden your horizons. Consideration for local communities and the environment. Time to return to your true self. What you seek in travel is surely unique to each individual.
Feel free to consult with the Snow Country Tourism Area.
