update content_bodies set title = 'Matsunoyama Dining in 美人林 2022', description = '持続可能性。そのお手本が日本の里山には、いまもなお残されています。
里山の営みは、容赦なく降り続く豪雪によって、幾度となく寸断され、脅かされ、
それでもまた立ちあがって、自然と共存しながら受け継がれてきました。
その壮大なる里山ストーリーを、世界の「TAKAZAWA」が料理で再構築する松之山ダイニング。
「TAKAZAWA」によって語られる里山ストーリーは、今年で4回目になります。
この夏は、いったいどんな物語を魅せてくれるでしょう。' where id = 'FfogICH-36S52GKLQdY8J';
update content_bodies set title = 'Matsunoyama Dining in 美人林 2022', description = 'Sustainability. The model for it still remains in Japan''s satoyama.
The activities of the satoyama have been repeatedly disrupted and threatened by the relentless heavy snowfall,
yet they have risen again, inheriting the tradition while coexisting with nature.
Matsunoyama Dining, which reconstructs this grand satoyama story through cuisine, is presented by the world-renowned ''TAKAZAWA''.
This year marks the fourth time the satoyama story is told by ''TAKAZAWA''.
What kind of story will it showcase this summer?' where id = 'I2xDJ0Q3oMnWlhL04f_1A';
