update content_bodies set title = '上信越高原国立公園の自然に囲まれた秘境の一軒宿', description = '文化財に指定された木造の建物で、伝統的な旅館の風情を味わえる。自然に湧き出る温泉を維持していくためにモニタリングを行い、持続可能性に配慮した経営をしている。周辺の国有林の生物多様性復元を目指す取り組みにも参加している。

